int probe_usb_interface(struct usb_interface *intf, const struct usb_device_id *id) {
    struct device_config *host_config, *device_config;
    int ret;

    host_config = kmalloc(sizeof(*host_config), GFP_KERNEL);
    if (!host_config)
        return -ENOMEM;

    device_config = kmalloc(sizeof(*device_config), GFP_KERNEL);
    if (!device_config) {
        kfree(host_config);
        return -ENOMEM;
    }

    ret = usb_control_msg(interface_to_usbdev(intf), usb_sndctrlpipe(interface_to_usbdev(intf), 0),
                          USB_REQ_SET_CONFIGURATION, USB_DIR_OUT | USB_TYPE_STANDARD | USB_RECIP_DEVICE,
                          1, 0, NULL, 0, USB_CTRL_MSG_TIMEOUT);
    if (ret < 0) {
        kfree(device_config);
        kfree(host_config);
        return ret;
    }

    ret = usb_get_device_config(interface_to_usbdev(intf), 1, device_config);
    if (ret < 0) {
        kfree(device_config);
        kfree(host_config);
        return ret;
    }

    if (device_config->num_interfaces != 1) {
        kfree(device_config);
        kfree(host_config);
        return -EINVAL;
    }

    intf->needs_remote_wakeup = 1;

    ret = create_can_device(intf, host_config);
    if (ret < 0) {
        kfree(device_config);
        kfree(host_config);
        return ret;
    }

    return 0;
}

int probe_usb_interface(struct usb_interface *intf, const struct usb_device_id *id) {
    struct device_config *host_config = NULL;
    struct device_config *dev_config = NULL;
    int ret = 0;

    host_config = kmalloc(sizeof(struct device_config), GFP_KERNEL);
    if (!host_config) {
        ret = -ENOMEM;
        goto error;
    }

    dev_config = kmalloc(sizeof(struct device_config), GFP_KERNEL);
    if (!dev_config) {
        ret = -ENOMEM;
        goto free_host_config;
    }

    ret = usb_control_msg(interface_to_usbdev(intf), usb_sndctrlpipe(interface_to_usbdev(intf), 0),
                          SET_HOST_FORMAT, USB_TYPE_CLASS | USB_RECIP_INTERFACE, 0, 0,
                          host_config, sizeof(struct device_config), USB_CTRL_TIMEOUT);
    if (ret < 0)
        goto free_dev_config;

    ret = usb_control_msg(interface_to_usbdev(intf), usb_rcvctrlpipe(interface_to_usbdev(intf), 0),
                          GET_DEV_CONFIG, USB_TYPE_CLASS | USB_RECIP_INTERFACE, 0, 0,
                          dev_config, sizeof(struct device_config), USB_CTRL_TIMEOUT);
    if (ret < 0)
        goto free_dev_config;

    if (dev_config->num_interfaces < 1) {
        ret = -ENODEV;
        goto free_dev_config;
    }

    intf->cur_altsetting->driver_data = dev_config;

    return 0;

free_dev_config:
    kfree(dev_config);
free_host_config:
    kfree(host_config);
error:
    return ret;
}

int usb_probe_interface(struct usb_interface *intf, const struct usb_device_id *id) {
    struct device_config *host_config = NULL;
    struct device_config *dev_config = NULL;
    int ret = -ENOMEM;

    host_config = kmalloc(sizeof(struct device_config), GFP_KERNEL);
    if (!host_config)
        goto error;

    dev_config = kmalloc(sizeof(struct device_config), GFP_KERNEL);
    if (!dev_config)
        goto error;

    ret = usb_control_msg(intf->cur_altsetting->desc.bInterfaceNumber,
                          USB_DIR_OUT | USB_TYPE_CLASS | USB_RECIP_INTERFACE,
                          USB_HOST_FORMAT_SET, 0, 0, host_config, sizeof(*host_config), 1000);
    if (ret < 0)
        goto error;

    ret = usb_control_msg(intf->cur_altsetting->desc.bInterfaceNumber,
                          USB_DIR_IN | USB_TYPE_CLASS | USB_RECIP_INTERFACE,
                          USB_DEVICE_CONFIG_GET, 0, 0, dev_config, sizeof(*dev_config), 1000);
    if (ret < 0)
        goto error;

    for (int i = 0; i < dev_config->num_interfaces; i++) {
        struct can_device *can_dev = alloc_can_device();

        if (!can_dev) {
            ret = -ENOMEM;
            goto error;
        }

        ret = register_can_device(can_dev);
        if (ret < 0) {
            free_can_device(can_dev);
            goto error;
        }
    }

    return 0;

error:
    kfree(host_config);
    kfree(dev_config);
    return ret;
}

int usb_interface_probe(struct usb_interface *intf, const struct usb_device_id *id) {
    struct device_config *host_config = NULL;
    struct device_config *dev_config = NULL;
    int ret = 0;

    host_config = kzalloc(sizeof(struct device_config), GFP_KERNEL);
    if (!host_config) {
        ret = -ENOMEM;
        goto error;
    }

    dev_config = kzalloc(sizeof(struct device_config), GFP_KERNEL);
    if (!dev_config) {
        ret = -ENOMEM;
        goto free_host_config;
    }

    ret = usb_control_msg(intf->cur_altsetting->desc.bInterfaceNumber, USB_DIR_OUT | USB_TYPE_CLASS | USB_RECIP_INTERFACE,
                          USB_REQ_SET_INTERFACE, 0, 0, NULL, 0, USB_CTRL_MSG_TIMEOUT);
    if (ret < 0)
        goto free_dev_config;

    ret = usb_get_device_config(intf->cur_altsetting->desc.bInterfaceNumber, dev_config);
    if (ret < 0)
        goto free_dev_config;

    if (dev_config->num_interfaces == 0) {
        ret = -EINVAL;
        goto free_dev_config;
    }

    intf->host_data = host_config;
    intf->dev_data = dev_config;

    for (int i = 0; i < dev_config->num_interfaces; ++i) {
        struct can_device *can_dev = can_device_create(intf, i);
        if (!can_dev) {
            ret = -ENOMEM;
            goto free_can_devices;
        }
    }

    return 0;

free_can_devices:
    for (int i = 0; i < dev_config->num_interfaces; ++i)
        can_device_free(intf, i);
free_dev_config:
    kfree(dev_config);
free_host_config:
    kfree(host_config);
error:
    return ret;
}

int probe_usb_interface(struct usb_interface *intf, const struct usb_device_id *id)
{
    struct usb_device *udev = interface_to_usbdev(intf);
    struct usb_host_config *host_config;
    struct usb_config_descriptor *config_desc;
    struct usb_interface *alt;
    struct usb_endpoint_descriptor *ep_desc;
    int i, j, interface_count;

    host_config = kzalloc(sizeof(*host_config), GFP_KERNEL);
    if (!host_config)
        return -ENOMEM;

    config_desc = kzalloc(sizeof(*config_desc), GFP_KERNEL);
    if (!config_desc) {
        kfree(host_config);
        return -ENOMEM;
    }

    if (usb_get_device_descriptor(udev, sizeof(*config_desc)) < 0) {
        kfree(config_desc);
        kfree(host_config);
        return -EIO;
    }

    memcpy(config_desc, &udev->descriptor, sizeof(*config_desc));

    interface_count = config_desc->bNumInterfaces;
    for (i = 0; i < interface_count; i++) {
        alt = kzalloc(sizeof(*alt), GFP_KERNEL);
        if (!alt) {
            for (j = 0; j < i; j++)
                kfree(intf[j]);
            kfree(config_desc);
            kfree(host_config);
            return -ENOMEM;
        }

        alt->altsetting = kzalloc(sizeof(*alt->altsetting), GFP_KERNEL);
        if (!alt->altsetting) {
            kfree(alt);
            for (j = 0; j < i; j++)
                kfree(intf[j]);
            kfree(config_desc);
            kfree(host_config);
            return -ENOMEM;
        }

        intf[i] = alt;
    }

    for (i = 0; i < interface_count; i++) {
        if (usb_set_interface(udev, i, 0) < 0) {
            for (j = i; j >= 0; j--) {
                kfree(intf[j]->altsetting);
                kfree(intf[j]);
            }
            kfree(config_desc);
            kfree(host_config);
            return -EIO;
        }
    }

    return 0;
}
